struct WaifuPcfxAudio {
    WaifuFmMusicTrack current_music; /* last music enum handed to us */
    uint8_t desired_track;           /* CD track we want (0 = silent) */
    uint8_t desired_loop;            /* WAIFU_CDDA_LOOP for looping music, 0 for one-shot */
    uint8_t active_track;            /* CD track we last issued a play for */
    uint8_t active_loop;             /* loop mode of the active play command */
    uint32_t active_seq;             /* cd-read seq at the moment we started it */
    uint32_t last_read_seq;          /* cd-read seq seen on the previous pump */
    uint8_t silence_stop_frames;     /* short CD-DA STOP retry after entering true silence */
};

static WaifuPcfxAudio g_audio;

#define WAIFU_PCFX_CDDA_BASE_VOLUME 56u   /* Slight music trim; 63 is full-scale. */
#define WAIFU_PCFX_CDDA_DUCK_VOLUME 38u   /* Temporary SFX duck, not a global music cut. */
#define WAIFU_PCFX_CDDA_DUCK_SHORT 24u
#define WAIFU_PCFX_CDDA_DUCK_LONG  58u
static uint8_t g_cdda_mix_volume = 255u;
static uint8_t g_cdda_duck_frames = 0u;
static uint8_t g_turn_jingle_guard_frames = 0u;

static void waifu_pcfx_cdda_apply_mix_volume(uint8_t volume)
{
    if (g_cdda_mix_volume == volume) return;
    waifu_pcfx_cdda_set_volume(volume, volume);
    g_cdda_mix_volume = volume;
}

static void waifu_pcfx_cdda_request_duck(uint8_t frames)
{
    if (frames > g_cdda_duck_frames) g_cdda_duck_frames = frames;
}

static void waifu_pcfx_cdda_pump_mix_volume(void)
{
    uint8_t target = g_cdda_duck_frames ? WAIFU_PCFX_CDDA_DUCK_VOLUME : WAIFU_PCFX_CDDA_BASE_VOLUME;
    waifu_pcfx_cdda_apply_mix_volume(target);
    if (g_cdda_duck_frames) --g_cdda_duck_frames;
    if (g_turn_jingle_guard_frames) --g_turn_jingle_guard_frames;
}

/* PC-FX game SFX are streamed from KING ADPCM samples loaded from sounds/.
   The PSG helpers remain only to silence channels that older builds may have
   left active before the ADPCM bank is ready. */
#define WAIFU_PCFX_PSG_CHANNELS 6
#define WAIFU_PCFX_PSG_SFX_VOICES 6
#define WAIFU_PCFX_PSG_CLOCK_DIV32 111875u /* 3.58 MHz / 32, matching liberis docs. */

typedef enum WaifuPcfxPsgWaveId {
    PSG_WAVE_SQUARE = 0,
    PSG_WAVE_PULSE,
    PSG_WAVE_TRIANGLE,
    PSG_WAVE_SOFT,
    PSG_WAVE_SAW,
    PSG_WAVE_PLUCK,
    PSG_WAVE_BELL,
    PSG_WAVE_METAL,
    PSG_WAVE_THIN
} WaifuPcfxPsgWaveId;

#define PSG_STEP_NOISE 0x01u

typedef struct WaifuPcfxPsgStep {
    uint8_t wave_id;
    uint8_t flags;
    uint8_t duration;
    uint8_t vol0;
    uint8_t vol1;
    uint8_t pan_l;
    uint8_t pan_r;
    uint16_t hz0;
    uint16_t hz1;
    uint8_t noise0;
    uint8_t noise1;
} WaifuPcfxPsgStep;

typedef struct WaifuPcfxPsgVoice {
    uint8_t active;
    uint8_t channel;
    uint8_t frame;
    uint8_t step_index;
    uint8_t step_count;
    uint8_t loaded_wave;
    const WaifuPcfxPsgStep *steps;
    uint8_t duration;
    uint8_t volume0;
    uint8_t volume1;
    uint8_t pan_l;
    uint8_t pan_r;
    uint8_t noise;
    uint8_t noise0;
    uint8_t noise1;
    uint16_t age;
    uint16_t max_age;
    uint16_t period0;
    uint16_t period1;
} WaifuPcfxPsgVoice;

