static const uint8_t *psg_wave_ptr(uint8_t wave_id)
{
    switch ((WaifuPcfxPsgWaveId)wave_id) {
    case PSG_WAVE_PULSE:    return g_psg_wave_pulse;
    case PSG_WAVE_TRIANGLE: return g_psg_wave_triangle;
    case PSG_WAVE_SOFT:     return g_psg_wave_soft;
    case PSG_WAVE_SAW:      return g_psg_wave_saw;
    case PSG_WAVE_PLUCK:    return g_psg_wave_pluck;
    case PSG_WAVE_BELL:     return g_psg_wave_bell;
    case PSG_WAVE_METAL:    return g_psg_wave_metal;
    case PSG_WAVE_THIN:     return g_psg_wave_thin;
    case PSG_WAVE_SQUARE:
    default:                return g_psg_wave_square;
    }
}

static uint16_t psg_period_from_hz(uint16_t hz)
{
    uint32_t p;
    if (hz == 0) return 0;
    p = (WAIFU_PCFX_PSG_CLOCK_DIV32 + (uint32_t)hz / 2u) / (uint32_t)hz;
    if (p < 1u) p = 1u;
    if (p > 0x0FFFu) p = 0x0FFFu;
    return (uint16_t)p;
}

static uint16_t lerp_u16(uint16_t a, uint16_t b, uint8_t frame, uint8_t duration)
{
    int32_t d;
    if (duration <= 1) return b;
    d = (int32_t)b - (int32_t)a;
    return (uint16_t)((int32_t)a + (d * (int32_t)frame) / (int32_t)(duration - 1u));
}

static uint8_t lerp_u8(uint8_t a, uint8_t b, uint8_t frame, uint8_t duration)
{
    int d;
    if (duration <= 1) return b;
    d = (int)b - (int)a;
    return (uint8_t)((int)a + (d * (int)frame) / (int)(duration - 1u));
}

static void psg_channel_silence(uint8_t ch, uint8_t guard_frames)
{
    if (ch >= WAIFU_PCFX_PSG_CHANNELS) return;
    eris_low_psg_set_channel(ch);
    eris_low_psg_set_noise(0, 0);
    eris_low_psg_set_freq(0);
    eris_low_psg_set_balance(0, 0);
    eris_low_psg_set_volume(0, 0, 0);
    g_psg_off_guard[ch] = guard_frames;
}

static void psg_channel_off(uint8_t ch)
{
    psg_channel_silence(ch, 4u);
}

static void psg_channel_prepare_start(uint8_t ch)
{
    if (ch >= WAIFU_PCFX_PSG_CHANNELS) return;
    g_psg_off_guard[ch] = 0u;
    psg_channel_silence(ch, 0u);
}

static void psg_load_wave(uint8_t ch, const uint8_t *wave)
{
    int i;
    eris_low_psg_set_channel(ch);
    eris_low_psg_set_volume(0, 0, 0);
    eris_low_psg_set_noise(0, 0);
    for (i = 0; i < 32; ++i) eris_low_psg_waveform_data((uint8_t)(wave[i] & 31u));
}

#define PSG_TONE(w,d,h0,h1,v0,v1,l,r) \
    { (uint8_t)(w), 0, (uint8_t)(d), (uint8_t)(v0), (uint8_t)(v1), (uint8_t)(l), (uint8_t)(r), (uint16_t)(h0), (uint16_t)(h1), 0, 0 }
#define PSG_NOISE(d,n0,n1,v0,v1,l,r) \
    { PSG_WAVE_SQUARE, PSG_STEP_NOISE, (uint8_t)(d), (uint8_t)(v0), (uint8_t)(v1), (uint8_t)(l), (uint8_t)(r), 0, 0, (uint8_t)(n0), (uint8_t)(n1) }
#define PSG_REST(d) \
    { PSG_WAVE_SQUARE, 0, (uint8_t)(d), 0, 0, 0, 0, 0, 0, 0, 0 }
#define PSG_COUNT(a) ((uint8_t)(sizeof(a) / sizeof((a)[0])))

